using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── CalculateTotal: DataRow-driven tests ───────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.15, 0.00, DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.20, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} but got {result}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Tax rate below 0")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ─── ApplyDiscount: DynamicData-driven tests ────────────────────────────

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100.00m, 0m, 100.00m, "No discount"],
        [100.00m, 10m, 90.00m, "10% off"],
        [100.00m, 50m, 50.00m, "50% off"],
        [100.00m, 100m, 0.00m, "100% off (free)"],
        [49.99m, 25m, 37.4925m, "Fractional result"],
        [0.00m, 50m, 0.00m, "Zero price with discount"],
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData), DynamicDataSourceType.Property,
        DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Scenario: {scenario}");
    }

    public static string GetDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => $"{methodInfo.Name} - {data[3]}";

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Discount below 0%")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discount));
    }

    // ─── DynamicData from a method (alternative pattern) ────────────────────

    public static IEnumerable<object[]> GetBulkOrderScenarios()
    {
        // Simulate scenarios that might come from config or complex setup
        yield return [9.99m, 100, 0.07m, 1068.93m];
        yield return [1.50m, 1000, 0.0m, 1500.00m];
        yield return [250.00m, 2, 0.20m, 600.00m];
    }

    [TestMethod]
    [DynamicData(nameof(GetBulkOrderScenarios), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkOrders_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }
}

